#include <stdio.h>
int main(void) {
    char ch = 0;
    scanf("%c", &ch);
    if (ch >= 'A' && ch <= 'Z')
        ch = (char)(ch + 32);
    else if (ch >= 'a' && ch <= 'z')
        ch = (char)(ch - 32);
    printf("%c\n", ch);
    return 0;
}

#include <stdio.h>
int main(void) {
    char ch = 0;
    scanf("%c", &ch);
    if (ch >= 'a' && ch <= 'z')
        ch = (char)((ch - 'a' + 5) % 26 + 'a');
    else if (ch >= 'A' && ch <= 'Z')
        ch = (char)((ch - 'A' + 5) % 26 + 'A');
    printf("%c\n", ch);
    return 0;
}

